describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(1_500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("sum can exceed subtotal (clamping is done by Cart)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800),
          new FixedAmountDiscountPolicy(800),
        ],
        "sum",
      );
      // Each returns min(800,1000)=800, sum = 1600 which exceeds 1000
      expect(composite.computeDiscountCents(1_000)).toBe(1_600);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // 10% of 5000 = 500, plus 200 = 700
      expect(composite.computeDiscountCents(5_000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on the remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining = 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(1_900);
    });

    it("ordering matters in chain mode", () => {
      const fixedFirst = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1_000), // 1000 off 10000, remaining = 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900
        ],
        "chain",
      );

      const percentFirst = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining = 9000
          new FixedAmountDiscountPolicy(1_000), // 1000 off 9000
        ],
        "chain",
      );

      expect(fixedFirst.computeDiscountCents(10_000)).toBe(1_900);
      expect(percentFirst.computeDiscountCents(10_000)).toBe(2_000);
    });

    it("stops accumulating when remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1_000),
          new FixedAmountDiscountPolicy(1_000),
        ],
        "chain",
      );
      // First takes 1000 from 1000, remaining = 0; second gets 0
      expect(composite.computeDiscountCents(1_000)).toBe(1_000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });
  });
});

