describe("Cart — totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2 × 1000 = 2000
    cart.add(productB, 1); // 1 × 2000 = 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4_000);
  });

  it("empty cart has zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500);
    expect(totals.totalCents).toBe(500); // 1000 - 500 + 0 tax + 0 ship
  });

  it("clamps discount that exceeds subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1_000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
    cart.add(productA, 1); // subtotal = 1000, discount = 200, taxable = 800
    const totals = cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    expect(totals.taxCents).toBe(80);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("computes shipping on discounted subtotal and lines", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(0),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalled();
    expect(totals.shippingCents).toBe(599);
    expect(totals.totalCents).toBe(1_000 + 599);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("pipeline order: subtotal → discount → tax → shipping → total", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1_000),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(270), // e.g. 9% of 3000
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator, region: "US" });
    cart.add(productA, 2); // 2×1000 = 2000
    cart.add(productB, 1); // 1×2000 = 2000
    // subtotal = 4000, discount = 1000 (clamped), discounted = 3000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4_000);
    expect(totals.discountCents).toBe(1_000);
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(3_000, "US");
    expect(totals.taxCents).toBe(270);
    expect(totals.shippingCents).toBe(500);
    expect(totals.totalCents).toBe(3_000 + 270 + 500);
  });

  it("uses default region US when not specified", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });
});

