import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 for any positive taxable amount", () => {
    expect(calc.computeTaxCents(10_000, "US")).toBe(0);
  });

  it("returns 0 for zero", () => {
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for any region", () => {
    expect(calc.computeTaxCents(5_000, "FR")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative default rate", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects default rate above 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN default rate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects a region rate above 1", () => {
      expect(() => new RegionalTaxCalculator({ US: 1.5 })).toThrow(RangeError);
    });

    it("rejects a negative region rate", () => {
      expect(() => new RegionalTaxCalculator({ US: -0.1 })).toThrow(RangeError);
    });

    it("rejects NaN region rate", () => {
      expect(() => new RegionalTaxCalculator({ US: NaN })).toThrow(RangeError);
    });

    it("accepts valid rates", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 0.0875, FR: 0.2 }, 0.1),
      ).not.toThrow();
    });

    it("accepts 0 and 1 as boundary rates", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 0, FR: 1 }, 0),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("uses the region-specific rate", () => {
      // 8.75% of 10000 = 875.0
      expect(calc.computeTaxCents(10_000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 10000 = 500
      expect(calc.computeTaxCents(10_000, "GB")).toBe(500);
    });

    it("rounds down to nearest cent", () => {
      // 8.75% of 101 = 8.8375 → 8
      expect(calc.computeTaxCents(101, "US-CA")).toBe(8);
    });

    it("returns 0 for zero taxable amount", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable amount", () => {
      expect(calc.computeTaxCents(-1_000, "US-CA")).toBe(0);
    });

    it("defaults to 0 rate when no default is specified", () => {
      const noDefault = new RegionalTaxCalculator({ US: 0.1 });
      expect(noDefault.computeTaxCents(10_000, "GB")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax using rate from provider", async () => {
